

CREATE TABLE `addition` (
  `id_addition` int(11) NOT NULL AUTO_INCREMENT,
  `idPatient` varchar(200) DEFAULT NULL,
  `idRDV` int(10) NOT NULL,
  `idMedecin` varchar(200) NOT NULL,
  `date_cons` date NOT NULL,
  `heure` time(6) NOT NULL,
  `addition` int(100) NOT NULL,
  PRIMARY KEY (`id_addition`)
) ENGINE=MyISAM AUTO_INCREMENT=9871 DEFAULT CHARSET=latin1;




CREATE TABLE `all_examens` (
  `idExamen` int(7) NOT NULL AUTO_INCREMENT,
  `typeExamen` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `objectif` mediumtext COLLATE utf8_unicode_ci NOT NULL,
  `principe` mediumtext COLLATE utf8_unicode_ci NOT NULL,
  `dossierApporter` mediumtext COLLATE utf8_unicode_ci NOT NULL,
  `precautions` mediumtext COLLATE utf8_unicode_ci NOT NULL,
  PRIMARY KEY (`idExamen`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `amis` (
  `id_amitie` int(11) NOT NULL AUTO_INCREMENT,
  `monID` varchar(255) NOT NULL,
  `amiID` varchar(255) NOT NULL,
  `demande` int(2) NOT NULL DEFAULT '0' COMMENT '0: demandé;  1:amis;',
  PRIMARY KEY (`id_amitie`)
) ENGINE=MyISAM AUTO_INCREMENT=22 DEFAULT CHARSET=latin1;




CREATE TABLE `cabinet` (
  `idCabinet` int(11) NOT NULL AUTO_INCREMENT,
  `nomCabinet` varchar(255) NOT NULL,
  `adresseCabinet` varchar(255) NOT NULL,
  `telCabinet` varchar(20) NOT NULL,
  `longitudeCabinet` varchar(11) NOT NULL,
  `latitudeCabinet` varchar(11) NOT NULL,
  `dateDhadesion` datetime NOT NULL,
  `ouverture` time(6) NOT NULL,
  `fermeture` time(6) NOT NULL,
  `nbrPatientParSeance` int(1) NOT NULL,
  PRIMARY KEY (`idCabinet`)
) ENGINE=MyISAM AUTO_INCREMENT=9 DEFAULT CHARSET=utf8;




CREATE TABLE `caisse` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `idConsultation` varchar(100) NOT NULL,
  `prix` decimal(12,2) NOT NULL,
  `date` datetime(6) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=34 DEFAULT CHARSET=latin1;




CREATE TABLE `consultations` (
  `idConsultation` varchar(100) COLLATE utf8_unicode_ci NOT NULL,
  `idPatient` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `idRendezvous` varchar(7) COLLATE utf8_unicode_ci DEFAULT NULL,
  `idMedecin` int(7) NOT NULL,
  `conclusion` text COLLATE utf8_unicode_ci NOT NULL,
  `heureConsultation` datetime NOT NULL,
  `etatCons` int(11) NOT NULL DEFAULT '0' COMMENT '1: open 0 : close',
  `motifCons` text COLLATE utf8_unicode_ci,
  PRIMARY KEY (`idConsultation`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `depenses` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `remarque` varchar(250) DEFAULT NULL,
  `depense` int(200) NOT NULL,
  `idMedecin` varchar(200) NOT NULL,
  `dateAjout` date NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=28 DEFAULT CHARSET=latin1;




CREATE TABLE `details_medicament` (
  `idDetailsMedicament` int(11) NOT NULL,
  `NUM_ENREGISTREMENT` varchar(59) DEFAULT NULL,
  `code` varchar(10) DEFAULT NULL,
  `DENOMINATION_COMMUNE_INTERNATIONALE` varchar(193) DEFAULT NULL,
  `COND` varchar(574) DEFAULT NULL,
  `LISTE` varchar(11) DEFAULT NULL,
  `P1` varchar(59) DEFAULT NULL,
  `P2` varchar(34) DEFAULT NULL,
  `OBS` varchar(69) DEFAULT NULL,
  `LABORATOIRES_DETENTEUR_DE_LA_DECISION_DENREGISTREMENT` varchar(75) DEFAULT NULL,
  `PAYS_DU_LABORATOIRE_DETENTEUR_DE_LA_DECISION_DENREGISTREMENT` varchar(21) DEFAULT NULL,
  `DATE_DENREGISTREMENT_INITIAL` date DEFAULT NULL,
  `DATE_DENREGISTREMENT_FINAL` date DEFAULT NULL,
  `TYPE` varchar(13) DEFAULT NULL,
  `STATUT` varchar(49) DEFAULT NULL,
  `DUREE_DE_STABILITE` varchar(56) DEFAULT NULL,
  `PRIX_PORTE_SUR_LA_DECISION_DENREGISTREMENT` varchar(138) DEFAULT NULL,
  `REMBOURSEMENT` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`idDetailsMedicament`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;




CREATE TABLE `dossierpatient` (
  `id_document` int(11) NOT NULL AUTO_INCREMENT,
  `idPatient` varchar(200) NOT NULL,
  `path` varchar(200) NOT NULL,
  `id_ajouteur` varchar(200) NOT NULL,
  `date_ajout` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id_document`)
) ENGINE=MyISAM AUTO_INCREMENT=390 DEFAULT CHARSET=latin1;




CREATE TABLE `duree_rdv` (
  `id_duree_rdv` int(11) NOT NULL AUTO_INCREMENT,
  `idMedCab` int(7) NOT NULL,
  `duree` int(40) NOT NULL DEFAULT '30',
  PRIMARY KEY (`id_duree_rdv`)
) ENGINE=MyISAM AUTO_INCREMENT=8 DEFAULT CHARSET=latin1;




CREATE TABLE `dureetemporelleentrelesseances` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `espace_entre_seances` int(50) NOT NULL DEFAULT '0' COMMENT 'Nbr de minutes entre les séances',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=latin1;




CREATE TABLE `emplacement_fiche_patient` (
  `id_emplacement` int(11) NOT NULL AUTO_INCREMENT,
  `idPatient` varchar(200) NOT NULL,
  `armoire` varchar(200) NOT NULL DEFAULT 'Non Enregistre',
  `boite` varchar(200) NOT NULL DEFAULT 'Non Enregistre',
  PRIMARY KEY (`id_emplacement`)
) ENGINE=MyISAM AUTO_INCREMENT=27 DEFAULT CHARSET=latin1;




CREATE TABLE `emploi_du_temps` (
  `id_emploiDT` int(11) NOT NULL AUTO_INCREMENT,
  `identifiant` varchar(200) NOT NULL,
  `typeCompte` int(11) NOT NULL,
  `jour` varchar(11) NOT NULL COMMENT '1:Dimanche  2:Lundi ...',
  `debut_service` time NOT NULL,
  `fin_service` time NOT NULL,
  `etat` varchar(11) NOT NULL COMMENT '1: dispo 2:conge...',
  PRIMARY KEY (`id_emploiDT`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;




CREATE TABLE `enteteord` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `nom` varchar(50) NOT NULL,
  `dateDajout` date NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;




CREATE TABLE `examens` (
  `idExamen` int(7) NOT NULL AUTO_INCREMENT,
  `typeExamen` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `objectif` mediumtext COLLATE utf8_unicode_ci NOT NULL,
  `principe` mediumtext COLLATE utf8_unicode_ci NOT NULL,
  `dossierApporter` mediumtext COLLATE utf8_unicode_ci NOT NULL,
  `precautions` mediumtext COLLATE utf8_unicode_ci NOT NULL,
  PRIMARY KEY (`idExamen`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `freqmedicament` (
  `idfreq` int(50) NOT NULL AUTO_INCREMENT,
  `frequence` varchar(50) NOT NULL,
  PRIMARY KEY (`idfreq`)
) ENGINE=MyISAM AUTO_INCREMENT=7 DEFAULT CHARSET=latin1;




CREATE TABLE `gestionexamen` (
  `idgestionExamen` int(7) NOT NULL AUTO_INCREMENT,
  `idAdmin` int(7) NOT NULL,
  `idExamen` int(7) NOT NULL,
  `typeGestionexamen` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `dateGestionexamen` date NOT NULL,
  PRIMARY KEY (`idgestionExamen`),
  KEY `idAdmin` (`idAdmin`),
  KEY `idExamen` (`idExamen`),
  CONSTRAINT `gestionexamen_ibfk_2` FOREIGN KEY (`idExamen`) REFERENCES `all_examens` (`idExamen`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `gestionmedicament` (
  `idGestionMedicament` int(7) NOT NULL AUTO_INCREMENT,
  `idAdmin` int(7) NOT NULL,
  `idMedicament` int(7) NOT NULL,
  `typeGestionMedicamens` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `dateGestionsmedicament` date NOT NULL,
  PRIMARY KEY (`idGestionMedicament`),
  KEY `idAdmin` (`idAdmin`),
  KEY `idMedicament` (`idMedicament`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `gestionrecettepracitien` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `idMedecin` varchar(200) NOT NULL,
  `pourcentage` int(3) NOT NULL,
  `dtaemodif` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=14 DEFAULT CHARSET=latin1;




CREATE TABLE `gestionspecialite` (
  `idGestionpecialite` int(7) NOT NULL AUTO_INCREMENT,
  `idAdmin` int(7) NOT NULL,
  `idSpecialite` int(7) NOT NULL,
  `typeGestionspecialite` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `dateGestionspecialite` date NOT NULL,
  PRIMARY KEY (`idGestionpecialite`),
  KEY `idAdmin` (`idAdmin`),
  KEY `idSpecialite` (`idSpecialite`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `historique` (
  `idhistorique` int(100) NOT NULL AUTO_INCREMENT,
  `datehistorique` datetime NOT NULL,
  `opperation` varchar(40) NOT NULL,
  `idCabinet` int(100) NOT NULL,
  `faiseur` varchar(200) NOT NULL,
  `sujet` varchar(200) NOT NULL,
  PRIMARY KEY (`idhistorique`)
) ENGINE=MyISAM AUTO_INCREMENT=3385 DEFAULT CHARSET=latin1;




CREATE TABLE `historiquecons` (
  `idhistoriqueCons` int(100) NOT NULL AUTO_INCREMENT,
  `idConsultation` varchar(100) NOT NULL,
  `idCabinet` int(100) NOT NULL,
  `dateHeureHistoCons` datetime NOT NULL,
  PRIMARY KEY (`idhistoriqueCons`)
) ENGINE=MyISAM AUTO_INCREMENT=62 DEFAULT CHARSET=latin1;




CREATE TABLE `jours_ouvrables` (
  `id` int(6) NOT NULL AUTO_INCREMENT,
  `jour` varchar(8) NOT NULL,
  `decision` int(1) DEFAULT '0' COMMENT '0:ouvert 1:fermé',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=8 DEFAULT CHARSET=latin1;




CREATE TABLE `lit` (
  `id_lit` int(11) NOT NULL AUTO_INCREMENT,
  `num_lit` varchar(11) NOT NULL,
  `nature_lit` varchar(100) NOT NULL,
  `etat_lit` int(3) NOT NULL DEFAULT '1' COMMENT '0: desactiver 1 : libre 2 : occupe 3: en panne',
  `id_emplacement` int(11) DEFAULT NULL,
  `motif_supp_lit` text,
  PRIMARY KEY (`id_lit`)
) ENGINE=MyISAM AUTO_INCREMENT=5 DEFAULT CHARSET=latin1;




CREATE TABLE `materiel` (
  `idMateriel` int(11) NOT NULL AUTO_INCREMENT,
  `nom` varchar(100) NOT NULL,
  `numeroSerie` varchar(100) NOT NULL,
  `etatMateriel` int(3) NOT NULL DEFAULT '1' COMMENT '0: desactiver 1 : libre 2 : occupe 3: en panne',
  `motif_supp_materiel` text,
  PRIMARY KEY (`idMateriel`)
) ENGINE=MyISAM AUTO_INCREMENT=7 DEFAULT CHARSET=latin1;




CREATE TABLE `medecin` (
  `idMedecin` varchar(200) NOT NULL,
  `nomMedecin` varchar(255) NOT NULL,
  `prenomMedecin` varchar(255) NOT NULL,
  `dateNaissMedecin` date NOT NULL,
  `lieuNaissMedecin` varchar(255) NOT NULL,
  `adresseMedecin` varchar(255) NOT NULL,
  `emailMedecin` varchar(255) NOT NULL,
  `numTelMedecin` varchar(255) NOT NULL,
  `sexeMedecin` varchar(12) NOT NULL,
  `groupageMedecin` varchar(5) NOT NULL,
  PRIMARY KEY (`idMedecin`)
) ENGINE=MyISAM AUTO_INCREMENT=3 DEFAULT CHARSET=utf8;




CREATE TABLE `medicament` (
  `idMedicament` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(10) DEFAULT NULL,
  `nomMedicament` varchar(271) DEFAULT NULL,
  `typeMedicament` varchar(93) DEFAULT NULL,
  `dosageMedicament` varchar(290) DEFAULT NULL,
  PRIMARY KEY (`idMedicament`)
) ENGINE=MyISAM AUTO_INCREMENT=4629 DEFAULT CHARSET=latin1;




CREATE TABLE `notifications` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(250) NOT NULL,
  `message` text NOT NULL,
  `ntime` datetime DEFAULT NULL,
  `repeat` int(11) DEFAULT '1',
  `nloop` int(11) NOT NULL DEFAULT '1',
  `publish_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `iduser` varchar(255) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;




CREATE TABLE `ordonnance` (
  `idOrdonnance` int(100) NOT NULL AUTO_INCREMENT,
  `idMedecin` varchar(100) NOT NULL,
  `dateOrdonnance` datetime(6) NOT NULL,
  `quantiteMedicament` int(50) DEFAULT NULL,
  `idConsultation` varchar(100) NOT NULL,
  `typeOrdonnance` int(8) NOT NULL COMMENT '1: mÃ©dicament 2: orientation 3: vide  4:bilan',
  PRIMARY KEY (`idOrdonnance`)
) ENGINE=MyISAM AUTO_INCREMENT=119 DEFAULT CHARSET=latin1;




CREATE TABLE `pathologie` (
  `id_pathologie` int(11) NOT NULL AUTO_INCREMENT,
  `pathologie` varchar(200) NOT NULL,
  `details` text,
  `etat` int(1) DEFAULT NULL COMMENT '0: malade;  1:pas malade;',
  PRIMARY KEY (`id_pathologie`)
) ENGINE=MyISAM AUTO_INCREMENT=8 DEFAULT CHARSET=latin1;




CREATE TABLE `patient` (
  `idPatient` varchar(200) COLLATE utf8_unicode_ci NOT NULL,
  `nomPatient` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `prenomPatient` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `dateNaissPatient` varchar(20) COLLATE utf8_unicode_ci NOT NULL,
  `lieuNaissPatient` varchar(50) COLLATE utf8_unicode_ci NOT NULL DEFAULT '--',
  `adressePatient` varchar(50) COLLATE utf8_unicode_ci DEFAULT NULL,
  `emailPatient` varchar(50) COLLATE utf8_unicode_ci NOT NULL DEFAULT '-- ',
  `numTelPatient` varchar(20) COLLATE utf8_unicode_ci NOT NULL,
  `sexePatient` varchar(10) COLLATE utf8_unicode_ci NOT NULL,
  `groupagePatient` varchar(50) COLLATE utf8_unicode_ci NOT NULL DEFAULT '--',
  `medecin_prescripteur` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,
  `medecin_suiv` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `profession` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `bilan` text COLLATE utf8_unicode_ci,
  `phone_2` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL,
  `phone_3` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL,
  `patient_a_risque` int(1) NOT NULL DEFAULT '0' COMMENT '0: A risque  1: Sans risque',
  `motif_risque` text COLLATE utf8_unicode_ci,
  PRIMARY KEY (`idPatient`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `prix` (
  `idPrix` int(10) NOT NULL AUTO_INCREMENT,
  `idExamen` int(100) NOT NULL,
  `prixExamen` int(100) DEFAULT NULL,
  PRIMARY KEY (`idPrix`),
  KEY `idExamen` (`idExamen`)
) ENGINE=MyISAM AUTO_INCREMENT=23 DEFAULT CHARSET=latin1;




CREATE TABLE `prixconsultation` (
  `idPrixConsultation` int(100) NOT NULL AUTO_INCREMENT,
  `typeConsultation` varchar(100) NOT NULL,
  `prixConsultation` int(100) NOT NULL,
  PRIMARY KEY (`idPrixConsultation`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=latin1;




CREATE TABLE `programme_patient` (
  `id_programme` int(11) NOT NULL AUTO_INCREMENT,
  `idPatient` varchar(200) NOT NULL,
  `type_seance` varchar(100) NOT NULL DEFAULT 'simple',
  `statut` int(1) NOT NULL DEFAULT '0' COMMENT '0: crée 1: confirmée 2: terminée',
  PRIMARY KEY (`id_programme`)
) ENGINE=MyISAM AUTO_INCREMENT=7 DEFAULT CHARSET=latin1;




CREATE TABLE `rapport_medical` (
  `id_rapport_medical` int(100) NOT NULL AUTO_INCREMENT,
  `idConsultation` varchar(100) NOT NULL,
  `idPatient` varchar(200) NOT NULL,
  `nature_geste` varchar(100) DEFAULT NULL,
  `type_anesthesie` varchar(100) NOT NULL,
  `compte_rendu` text,
  `emplty` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id_rapport_medical`)
) ENGINE=MyISAM AUTO_INCREMENT=7 DEFAULT CHARSET=latin1;




CREATE TABLE `rdv` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `nomP` varchar(100) NOT NULL,
  `prenoP` varchar(100) NOT NULL,
  `mail` varchar(100) NOT NULL,
  `tel` varchar(20) NOT NULL,
  `dateRDV` varchar(20) NOT NULL,
  `heureRDV` time NOT NULL,
  `medecin` varchar(100) NOT NULL,
  `statut` int(1) NOT NULL DEFAULT '6' COMMENT '0: Absent 1: Present 2: En salle 3:Fini 4:Supprime 5: confirmé 6: non confirmé',
  `motifCons` text,
  `idMedecin` varchar(200) NOT NULL,
  `idPatient` varchar(200) DEFAULT NULL,
  `type` int(2) NOT NULL DEFAULT '0' COMMENT '0: simple 1: enligne  2: autres',
  `remarque_fin_seance` text,
  `patient_a_risque` int(1) NOT NULL DEFAULT '0' COMMENT '0: A risque  1: Sans risque',
  `motif_risque` text,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=15708 DEFAULT CHARSET=latin1;




CREATE TABLE `rel_patient_pathologie` (
  `id_relation` int(11) NOT NULL AUTO_INCREMENT,
  `idPatient` varchar(200) NOT NULL,
  `id_pathologie` int(11) NOT NULL,
  PRIMARY KEY (`id_relation`)
) ENGINE=MyISAM AUTO_INCREMENT=2999 DEFAULT CHARSET=latin1;




CREATE TABLE `rel_seance_patient` (
  `id_relation` int(11) NOT NULL AUTO_INCREMENT,
  `id_seance` int(11) NOT NULL,
  `idPatient` varchar(200) NOT NULL,
  PRIMARY KEY (`id_relation`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;




CREATE TABLE `rel_seance_rdv` (
  `id_relation` int(11) NOT NULL AUTO_INCREMENT,
  `id_seance` int(11) NOT NULL,
  `id` int(10) NOT NULL,
  PRIMARY KEY (`id_relation`)
) ENGINE=MyISAM AUTO_INCREMENT=15528 DEFAULT CHARSET=latin1;




CREATE TABLE `relation_materiel_slp` (
  `idRelMatSLP` int(11) NOT NULL AUTO_INCREMENT,
  `idMateriel` int(11) NOT NULL,
  `idSLP` int(11) DEFAULT NULL,
  `type` varchar(3) DEFAULT NULL COMMENT 'S: Salle;   L: Lit;   P:Patient',
  PRIMARY KEY (`idRelMatSLP`),
  KEY `idMateriel` (`idMateriel`)
) ENGINE=MyISAM AUTO_INCREMENT=5 DEFAULT CHARSET=latin1;




CREATE TABLE `relationexamcons` (
  `idRelExamCons` int(50) NOT NULL AUTO_INCREMENT,
  `idConsultation` varchar(100) NOT NULL,
  `typeExamen` varchar(50) NOT NULL,
  `resultExam` text,
  PRIMARY KEY (`idRelExamCons`)
) ENGINE=MyISAM AUTO_INCREMENT=161 DEFAULT CHARSET=latin1;




CREATE TABLE `relationmedcab` (
  `idMedCab` int(7) NOT NULL AUTO_INCREMENT,
  `idCabinet` int(7) NOT NULL,
  `idMedecin` varchar(200) CHARACTER SET utf8 NOT NULL,
  PRIMARY KEY (`idMedCab`),
  KEY `idCabinet` (`idCabinet`),
  KEY `idMedecin` (`idMedecin`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE TABLE `relationmediccons` (
  `idRelConsMedic` int(11) NOT NULL AUTO_INCREMENT,
  `idConsultation` varchar(100) NOT NULL,
  `idMedicament` int(100) NOT NULL,
  `dosage` varchar(100) DEFAULT NULL,
  `frequence` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`idRelConsMedic`)
) ENGINE=MyISAM AUTO_INCREMENT=345 DEFAULT CHARSET=latin1;




CREATE TABLE `relbilandemcons` (
  `idRelBilanCons` int(11) NOT NULL AUTO_INCREMENT,
  `idConsultation` varchar(100) NOT NULL,
  `typeExamen` varchar(50) NOT NULL,
  PRIMARY KEY (`idRelBilanCons`)
) ENGINE=MyISAM AUTO_INCREMENT=13 DEFAULT CHARSET=latin1;




CREATE TABLE `relcabexamens` (
  `idrelationcabexam` int(11) NOT NULL AUTO_INCREMENT,
  `idCabinet` int(11) NOT NULL,
  `idExamen` int(7) NOT NULL,
  PRIMARY KEY (`idrelationcabexam`)
) ENGINE=MyISAM AUTO_INCREMENT=17 DEFAULT CHARSET=latin1;




CREATE TABLE `relcabspecialite` (
  `idRelCabSpecialite` int(11) NOT NULL AUTO_INCREMENT,
  `idCabinet` int(11) NOT NULL,
  `idSpecialite` int(11) NOT NULL,
  PRIMARY KEY (`idRelCabSpecialite`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;




CREATE TABLE `relmedspecialite` (
  `idRelMedSpecialite` int(11) NOT NULL AUTO_INCREMENT,
  `idMedecin` int(11) NOT NULL,
  `idSpecialite` int(11) NOT NULL,
  PRIMARY KEY (`idRelMedSpecialite`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;




CREATE TABLE `relpatcab` (
  `idrelpatcab` int(100) NOT NULL AUTO_INCREMENT,
  `idPatient` varchar(255) NOT NULL,
  `idCabinet` varchar(255) NOT NULL,
  `etat` varchar(2) NOT NULL DEFAULT '1' COMMENT '1: visible dans le cabinet 0: bloqué',
  PRIMARY KEY (`idrelpatcab`),
  KEY `idCabinet` (`idCabinet`),
  KEY `idPatient` (`idPatient`)
) ENGINE=MyISAM AUTO_INCREMENT=3013 DEFAULT CHARSET=latin1;




CREATE TABLE `salle` (
  `id_salle` int(11) NOT NULL AUTO_INCREMENT,
  `num_nom_salle` varchar(40) NOT NULL,
  `etage_salle` varchar(3) NOT NULL,
  `type_salle` varchar(100) NOT NULL,
  `etat_salle` int(3) NOT NULL DEFAULT '1' COMMENT '0: desactiver 1 : libre 2 : occupe',
  `motif_supp_salle` text,
  PRIMARY KEY (`id_salle`)
) ENGINE=MyISAM AUTO_INCREMENT=4 DEFAULT CHARSET=latin1;




CREATE TABLE `seance` (
  `id_seance` int(11) NOT NULL AUTO_INCREMENT,
  `type_seance` varchar(100) NOT NULL DEFAULT 'simple',
  `jour` varchar(8) NOT NULL,
  `date` date NOT NULL,
  `heure` time(6) NOT NULL,
  `etat` int(1) NOT NULL DEFAULT '0' COMMENT '0: crée 1: ouverte 2: terminée',
  PRIMARY KEY (`id_seance`)
) ENGINE=MyISAM AUTO_INCREMENT=104659 DEFAULT CHARSET=latin1;




CREATE TABLE `sessions` (
  `sessions_id` int(11) NOT NULL AUTO_INCREMENT,
  `sessions_iduser` int(10) NOT NULL,
  `sessions_token` int(40) NOT NULL,
  `sessions_serial` int(40) NOT NULL,
  `sessions_date` varchar(10) NOT NULL,
  PRIMARY KEY (`sessions_id`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;




CREATE TABLE `specialite` (
  `idSpecialite` int(20) NOT NULL AUTO_INCREMENT,
  `nomSpecialite` varchar(200) NOT NULL,
  PRIMARY KEY (`idSpecialite`)
) ENGINE=MyISAM AUTO_INCREMENT=94 DEFAULT CHARSET=latin1;




CREATE TABLE `stats` (
  `id_stats` int(21) NOT NULL AUTO_INCREMENT,
  `type` varchar(100) NOT NULL,
  `date_insertion` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `init` int(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id_stats`)
) ENGINE=MyISAM AUTO_INCREMENT=7620 DEFAULT CHARSET=latin1;




CREATE TABLE `theme` (
  `idtheme` int(11) NOT NULL AUTO_INCREMENT,
  `idCabinet` int(11) NOT NULL DEFAULT '1',
  `idUser` varchar(200) NOT NULL,
  `nomTheme` varchar(100) NOT NULL,
  PRIMARY KEY (`idtheme`)
) ENGINE=MyISAM AUTO_INCREMENT=45 DEFAULT CHARSET=latin1;




CREATE TABLE `users` (
  `iduser` int(11) NOT NULL AUTO_INCREMENT,
  `login` varchar(255) NOT NULL,
  `password` varchar(255) NOT NULL,
  `typeCompte` int(11) NOT NULL COMMENT '1: patient; 2: medecin, 3: infermier, 4: adminCabinet, 5:staffCabinet, 0: superAdmin',
  `identifiant` varchar(200) NOT NULL,
  PRIMARY KEY (`iduser`)
) ENGINE=MyISAM AUTO_INCREMENT=61 DEFAULT CHARSET=utf8;


